CREATE TABLE public.institutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.institutions TO authenticated;
GRANT ALL ON public.institutions TO service_role;
ALTER TABLE public.institutions ENABLE ROW LEVEL SECURITY;
CREATE POLICY institutions_platform ON public.institutions FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'super_admin')) WITH CHECK (public.has_role(auth.uid(), 'super_admin'));
CREATE UNIQUE INDEX institutions_name_unique ON public.institutions (lower(trim(name)));
CREATE TABLE public.faculties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES public.institutions(id) ON DELETE RESTRICT, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id, institution_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.faculties TO authenticated;
GRANT ALL ON public.faculties TO service_role;
ALTER TABLE public.faculties ENABLE ROW LEVEL SECURITY;
CREATE POLICY faculties_platform ON public.faculties FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'super_admin')) WITH CHECK (public.has_role(auth.uid(), 'super_admin'));
CREATE UNIQUE INDEX faculties_name_unique ON public.faculties (institution_id, lower(trim(name)));
CREATE TABLE public.hierarchy_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, role text NOT NULL, institution_id uuid NOT NULL REFERENCES public.institutions(id) ON DELETE RESTRICT, faculty_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(faculty_id,institution_id) REFERENCES public.faculties(id,institution_id) ON DELETE RESTRICT, UNIQUE(user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.hierarchy_memberships TO authenticated;
GRANT ALL ON public.hierarchy_memberships TO service_role;
ALTER TABLE public.hierarchy_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_platform ON public.hierarchy_memberships FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'super_admin')) WITH CHECK (public.has_role(auth.uid(), 'super_admin'));
CREATE POLICY memberships_self ON public.hierarchy_memberships FOR SELECT TO authenticated USING (user_id=auth.uid());
ALTER TABLE public.departments ADD COLUMN faculty_id uuid REFERENCES public.faculties(id) ON DELETE RESTRICT;
CREATE INDEX departments_faculty_idx ON public.departments(faculty_id);
CREATE OR REPLACE FUNCTION public.can_access_hierarchy(_institution uuid, _faculty uuid DEFAULT NULL, _manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR EXISTS (SELECT 1 FROM public.hierarchy_memberships m JOIN public.institutions i ON i.id=m.institution_id WHERE m.user_id=auth.uid() AND m.institution_id=_institution AND i.status='active' AND (m.role='institution_admin' OR (NOT _manage AND m.role='faculty_admin' AND (_faculty IS NULL OR m.faculty_id=_faculty)))) $$;
REVOKE ALL ON FUNCTION public.can_access_hierarchy(uuid,uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_hierarchy(uuid,uuid,boolean) TO authenticated,service_role;
CREATE POLICY institutions_scope ON public.institutions FOR SELECT TO authenticated USING(public.can_access_hierarchy(id));
CREATE POLICY faculties_scope ON public.faculties FOR SELECT TO authenticated USING(public.can_access_hierarchy(institution_id,id));
CREATE POLICY faculties_institution_manage ON public.faculties FOR ALL TO authenticated USING(public.can_access_hierarchy(institution_id,id,true)) WITH CHECK(public.can_access_hierarchy(institution_id,id,true));
CREATE OR REPLACE FUNCTION public.can_access_department_hierarchy(_department uuid, _manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.departments d JOIN public.faculties f ON f.id=d.faculty_id WHERE d.id=_department AND public.can_access_hierarchy(f.institution_id,f.id,_manage)) $$;
REVOKE ALL ON FUNCTION public.can_access_department_hierarchy(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_department_hierarchy(uuid,boolean) TO anon,authenticated,service_role;
CREATE POLICY departments_hierarchy_scope ON public.departments AS RESTRICTIVE FOR SELECT USING (faculty_id IS NULL OR public.has_role(auth.uid(),'super_admin') OR id=public.get_user_department(auth.uid()) OR public.can_access_department_hierarchy(id));
CREATE POLICY departments_institution_manage ON public.departments FOR ALL TO authenticated USING(public.can_access_department_hierarchy(id,true)) WITH CHECK(EXISTS(SELECT 1 FROM public.faculties f WHERE f.id=faculty_id AND public.can_access_hierarchy(f.institution_id,f.id,true)));
CREATE OR REPLACE FUNCTION public.validate_hierarchy() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_TABLE_NAME='institutions' THEN IF length(trim(NEW.name))=0 OR length(NEW.name)>200 OR NEW.status NOT IN ('active','suspended','inactive') THEN RAISE EXCEPTION 'Invalid institution name or status'; END IF;
ELSIF TG_TABLE_NAME='faculties' THEN IF length(trim(NEW.name))=0 OR length(NEW.name)>200 THEN RAISE EXCEPTION 'Faculty name is required'; END IF; IF TG_OP='UPDATE' AND NEW.institution_id<>OLD.institution_id THEN RAISE EXCEPTION 'A faculty cannot move between institutions'; END IF;
ELSIF TG_TABLE_NAME='hierarchy_memberships' THEN IF NEW.role NOT IN ('institution_admin','faculty_admin') OR (NEW.role='institution_admin' AND NEW.faculty_id IS NOT NULL) OR (NEW.role='faculty_admin' AND NEW.faculty_id IS NULL) THEN RAISE EXCEPTION 'Choose a valid administrator scope'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER institutions_validate BEFORE INSERT OR UPDATE ON public.institutions FOR EACH ROW EXECUTE FUNCTION public.validate_hierarchy();
CREATE TRIGGER faculties_validate BEFORE INSERT OR UPDATE ON public.faculties FOR EACH ROW EXECUTE FUNCTION public.validate_hierarchy();
CREATE TRIGGER memberships_validate BEFORE INSERT OR UPDATE ON public.hierarchy_memberships FOR EACH ROW EXECUTE FUNCTION public.validate_hierarchy();
CREATE TRIGGER institutions_updated BEFORE UPDATE ON public.institutions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER faculties_updated BEFORE UPDATE ON public.faculties FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER memberships_updated BEFORE UPDATE ON public.hierarchy_memberships FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();